// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io/

const N_FRAMES = 150;
let theShader;
let back;
let front;

function preload() {
  theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(500, 500);
  imageMode(CENTER)

  back = createGraphics(width, height, WEBGL);
  back.shader(theShader);
  theShader.setUniform('u_resolution', [1, 1]);
  back.rect(0, 0, width, height);

  front = createGraphics(width, height);
  front.rectMode(CENTER);
}

function draw() {
  image(back, width/2, height/2);

  front.background(0);
  front.erase();
  front.strokeWeight(3);
  front.noFill();

  translate(width/2, height/2);
  if (frameCount%(2*N_FRAMES) > N_FRAMES) {
    rotate(PI/2);
  }

  let d = width/2;
  let n = 8;
  for (let i = 0; i < n; i++) {
    let myFrame = (frameCount-3*i)%N_FRAMES;
    let percent = myFrame/N_FRAMES;
    let x, y = (i+1/2)*(d/n) - d/2;
    if (myFrame < N_FRAMES/2) {
      percent = easeInOutQuint(percent*2)/2;
      x = percent*(width+d) - (d+width)/2;
    } else {
      percent = 1-easeInOutQuint(percent*2)/2;
      x = width/2 - percent*(width+d) + d/2;
    }
    //front.rect(x+width/2-1, y+height/2, d, d/n);
    for (let j = -n/2; j < n/2; j++) {
      front.rect(x+width/2+(j+1/2)*d/n-2, y+height/2, d/n, d/n)
    }
  }

  image(front, 0, 0);
}

// from https://easings.net/
function easeInOutQuint(x) {
  return x < 0.5 ? 16 * x * x * x * x * x : 1 - pow(-2 * x + 2, 5) / 2;
}

const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	varying vec2 vTexCoord;

	uniform vec2 u_resolution;
	uniform float u_time;

	void main() {
	  vec2 st = vTexCoord.xy/u_resolution.xy;
	  st.x *= u_resolution.x/u_resolution.y;

      vec3 col1 = vec3(1., 1., 0.);
      vec3 col2 = vec3(1., 0., 0.);
      float mixValue = distance(st.x+st.y, 1.);
      vec3 color = mix(col1,col2,mixValue);
	  gl_FragColor = vec4(color,1.0);
	}
`;

const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;

		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

		gl_Position = positionVec4;
	}
`;

